using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using DockSense.App.Platform;
using DockSense.Core;

namespace DockSense.App.Services;

/// <summary>The pixel-art icons (assets/icons, generated by tools/DockSense.IconGen) as WPF images, tray icons and files.</summary>
public static class IconAssets
{
    public const string App = "app";
    public const string Paused = "paused";

    public static string NameFor(DockMode mode, bool paused = false) => paused ? Paused : mode switch
    {
        DockMode.Egpu => "egpu",
        DockMode.Docked => "docked",
        _ => "handheld",
    };

    /// <summary>The 1x pixel image. Show it with NearestNeighbor scaling to keep hard pixel edges.</summary>
    public static ImageSource Image(string name)
    {
        var image = new BitmapImage(Uri($"{name}.png"));
        image.Freeze();
        return image;
    }

    /// <summary>The tray icon frame that matches the system small-icon size (16 px at 100%, 20 at 125%, ...).</summary>
    public static ImageSource TrayIcon(string name)
    {
        var target = NativeMethods.GetSystemMetricsForDpi(NativeMethods.SM_CXSMICON, NativeMethods.GetDpiForSystem());
        var decoder = new IconBitmapDecoder(Uri($"tray-{name}.ico"), BitmapCreateOptions.None, BitmapCacheOption.OnLoad);
        var frame = decoder.Frames
            .OrderBy(f => f.PixelWidth >= target ? 0 : 1)
            .ThenBy(f => Math.Abs(f.PixelWidth - target))
            .First();
        frame.Freeze();
        return frame;
    }

    /// <summary>Writes the 8x PNG to %LOCALAPPDATA%\DockSense\icons (toast notifications need a file) and returns its path.</summary>
    public static string ToastImagePath(string name)
    {
        var directory = Path.Combine(Log.DataDirectory, "icons");
        var path = Path.Combine(directory, $"{name}@8x.png");
        if (!File.Exists(path))
        {
            Directory.CreateDirectory(directory);
            var resource = Application.GetResourceStream(Uri($"{name}@8x.png"))
                ?? throw new FileNotFoundException($"Missing icon resource {name}@8x.png");
            using var input = resource.Stream;
            using var output = File.Create(path);
            input.CopyTo(output);
        }

        return path;
    }

    private static Uri Uri(string file) => new($"pack://application:,,,/Assets/{file}", UriKind.Absolute);
}
